import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {chromium} from 'playwright-core';

const origin='https://ech-fixture.invalid';
const actor='10000000-0000-4000-8000-000000000001';
const draftId='70000000-0000-4000-8000-000000000001';
const assets=new Map(await Promise.all([['/admin/','index.html','text/html'],['/admin/admin.js','admin.js','text/javascript'],['/admin/admin.css','admin.css','text/css']].map(async([url,file,contentType])=>[url,{contentType,body:await readFile(new URL('../../dist/admin/'+file,import.meta.url))}])));
async function fixture(browser,{reads=true,scheduleStatus=200,holdSchedule=false,scheduleVisits=[],scheduleClients=[],role='manager',create=true,entry='daily',applicationAdmin=false,technicalAdmin=false,scheduleCommands=false,profile=false,partners=[],inquiries=[],scheduleStaff=[],inquirySave='reject',accountFixture=false}={}) {
 const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,serviceWorkers:'block'});
 let authorized=true,sessionMode='normal',holdSession=false,releaseSession;const sessionGate=new Promise(resolve=>{releaseSession=resolve;});const requests=[],unexpected=[],errors=[];let releaseSave,releaseSchedule;const saveGate=new Promise(resolve=>{releaseSave=resolve;});const scheduleGate=new Promise(resolve=>{releaseSchedule=resolve;});
 await context.addInitScript(id=>{Object.defineProperty(crypto,'randomUUID',{value:()=>id});},draftId);
 await context.route('**/*',async route=>{const r=route.request(),u=new URL(r.url());requests.push({method:r.method(),path:u.pathname,body:r.postData()});
  if(u.origin!==origin){unexpected.push(r.url());return route.abort();}
  if(assets.has(u.pathname)&&r.method()==='GET')return route.fulfill(assets.get(u.pathname));
  if(u.pathname==='/favicon.ico')return route.fulfill({status:204});
  if(u.pathname==='/api/admin/session'&&r.method()==='GET'&&holdSession)await sessionGate;
  if(u.pathname==='/api/admin/session'&&r.method()==='GET'&&sessionMode==='failed')return route.fulfill({status:503,json:{error:'fictional unavailable'}});
  if(u.pathname==='/api/admin/session'&&r.method()==='GET')return authorized?route.fulfill({json:{authenticated:true,principal:{id:actor,email:'fictional@ech-fixture.invalid',technicalAdmin,applicationAdmin,operationalRole:role},capabilities:[role==='staff'?'leads.read_assigned':'leads.read_all',...(create?['leads.create']:[]),...(applicationAdmin?['users.manage','backup.export']:[]),...(technicalAdmin?['admin.status']:[])],operationsFeatures:{reads,scheduleCommands,scheduleRecurrence:false,visitActions:false}}}):route.fulfill({status:403,json:{error:'fixture denied'}});
  if(accountFixture&&u.pathname==='/api/admin/memberships'&&r.method()==='GET')return route.fulfill({json:{schema:1,items:[{userId:'10000000-0000-4000-8000-000000000002',email:'fictional-account@ech-fixture.invalid',displayName:'Fictional account',active:true,operationalRole:'staff',technicalAdmin:false,applicationAdmin:false,revision:1}]}});
  if(profile&&applicationAdmin&&u.pathname==='/api/admin/memberships'&&r.method()==='GET')return route.fulfill({json:{items:[{userId:actor,displayName:'Fictional staff member',active:true,operationalRole:'staff'}]}});
  if(profile&&u.pathname==='/api/admin/staff-profile'&&u.searchParams.get('view')==='pending')return route.fulfill({json:{schema:1,pending:false}});
  if(['/api/admin/memberships','/api/admin/access-requests'].includes(u.pathname)&&r.method()==='GET')return route.fulfill({status:503,json:{error:{code:'unavailable',message:'Fictional unavailable'}}});
  if(profile&&u.pathname==='/api/admin/staff-profile'&&r.method()==='GET')return route.fulfill({json:{schema:1,profile:{id:actor,revision:1,name:'Fictional worker',workerType:'care_aide',availability:'Fictional original',vacationStart:'',vacationEnd:'',credentials:[]},pending:null}});
  if(profile&&u.pathname==='/api/admin/staff-profile'&&r.method()==='POST'){await saveGate;return route.fulfill({json:{status:'pending_review',submissionId:'80000000-0000-4000-8000-000000000001'}});}
  if(u.pathname==='/api/admin/staff-profile'&&r.method()==='GET')return route.fulfill({status:404,json:{error:{code:'not_found',message:'Fictional profile unavailable'}}});
  if(['/api/admin/inquiries','/api/admin/partners'].includes(u.pathname)&&r.method()==='GET')return route.fulfill({json:{schema:1,mode:'shared',items:u.pathname.endsWith('/partners')?partners:inquiries,nextCursor:null}});
  if(u.pathname==='/api/admin/operations'&&r.method()==='GET'&&u.searchParams.has('from')){if(holdSchedule)await scheduleGate;if(scheduleStatus!==200)return route.fulfill({status:scheduleStatus,json:{error:'fictional unavailable'}});return route.fulfill({json:{schema:1,mode:'shared',visits:scheduleVisits,clients:scheduleClients,staff:role==='staff'?[{id:actor,name:'Fictional worker'}]:scheduleStaff}});}
  if(u.pathname==='/api/admin/logout'&&r.method()==='POST'){authorized=false;return route.fulfill({json:{ok:true}});}
  if(u.pathname==='/api/admin/inquiries'&&r.method()==='POST'){if(inquirySave==='pending')await saveGate;if(inquirySave!=='reject')return route.abort('failed');return route.fulfill({status:422,json:{error:'fictional no write'}});}
  unexpected.push(r.method()+' '+u.pathname+u.search);return route.abort();
 });
 const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message)); await page.goto(origin+'/admin/?view='+entry);await page.getByRole('heading',{name:entry==='daily'?'Today':'Operations',exact:true}).waitFor();
 return {context,page,requests,unexpected,errors,releaseSave,releaseSchedule,holdNextSession:()=>{holdSession=true;},releaseSession,setSessionMode:value=>{sessionMode=value;if(value==='changed')role='owner';},deny:()=>{authorized=false;}};
}
test('enlarged scrolled content is not covered by header menu and More remains usable',async()=>{const b=await chromium.launch({headless:true});try{for(const width of [320,390]){const f=await fixture(b),p=f.page;await p.setViewportSize({width,height:844});await p.evaluate(()=>{const nodes=[...document.querySelectorAll('body *')],sizes=nodes.map(x=>parseFloat(getComputedStyle(x).fontSize));nodes.forEach((x,i)=>x.style.setProperty('font-size',`${sizes[i]*2}px`,'important'));});const menu=p.getByRole('button',{name:'Open workspace menu'});const before=await menu.boundingBox();await p.mouse.wheel(0,600);await p.waitForTimeout(150);const after=await menu.boundingBox();assert.ok(after.y+after.height<=0,JSON.stringify({before,after}));const more=p.getByRole('navigation',{name:'Primary navigation'}).getByRole('button',{name:'More'});await more.focus();await p.keyboard.press('Enter');await p.getByRole('dialog',{name:'Workspace menu'}).waitFor();await p.keyboard.press('Escape');assert.equal(await more.evaluate(e=>e===document.activeElement),true);assert.deepEqual(f.errors,[]);await f.context.close();}}finally{await b.close();}});
test('schedule states clear the four cards at both phone widths',async()=>{
 const b=await chromium.launch({headless:true});
 try {
  for(const width of [320,390]) for(const state of ['populated','empty','unavailable']) {
   const client='20000000-0000-4000-8000-000000000001',now=Date.now();
   const visit={id:'30000000-0000-4000-8000-000000000001',clientId:client,workerId:null,service:'Home support',start:new Date(now-60000).toISOString(),end:new Date(now+60000).toISOString(),status:'Open',revision:1};
   const f=await fixture(b,{reads:state!=='unavailable',scheduleVisits:state==='populated'?[visit]:[],scheduleClients:state==='populated'?[{id:client,name:'Fictional client'}]:[]});
   try {
    const p=f.page;await p.setViewportSize({width,height:844});
    const cards=p.getByRole('region',{name:'Today actions'}),section=p.getByRole('region',{name:'Today schedule'});
    await section.waitFor();
    if(state==='populated') await section.getByText(/Home support.*Open/).waitFor();
    else if(state==='empty') await section.getByText('No visits scheduled today.',{exact:true}).waitFor();
    else await section.getByText(/unavailable/i).waitFor();
    assert.equal(await cards.locator('button').count(),4);
    const cardBox=await cards.boundingBox(),scheduleBox=await section.boundingBox();
    if(state!=='unavailable') {
     const attention=p.getByRole('region',{name:'Today’s visits needing attention'});
     const heading=attention.getByRole('heading',{name:'Today’s visits needing attention'});
     assert.ok((await heading.boundingBox()).y>=scheduleBox.y+scheduleBox.height,`attention summary must follow schedule at ${width}: ${state}`);
     assert.equal(await section.evaluate(e=>!!(e.compareDocumentPosition(e.parentElement.querySelector('h2'))&Node.DOCUMENT_POSITION_FOLLOWING)),true);
    }
    assert.ok(cardBox&&scheduleBox&&scheduleBox.y>=cardBox.y+cardBox.height,JSON.stringify({width,state,cardBox,scheduleBox}));
    if(state==='unavailable') assert.equal(f.requests.filter(r=>r.path==='/api/admin/operations').length,0);
    else assert.ok(f.requests.some(r=>r.path==='/api/admin/operations'&&r.method==='GET'));
    assert.equal(f.requests.filter(r=>r.method==='POST').length,0);
    assert.deepEqual(f.unexpected,[]);assert.deepEqual(f.errors,[]);
   } finally {await f.context.close();}
  }
 } finally {await b.close();}
});
test('schedule and attention retain semantic and visual order at breakpoints',async()=>{
 const b=await chromium.launch({headless:true});
 try {for(const width of [320,390,700,701,1200]) for(const state of ['populated','empty','unavailable','loading','failed']) {
  const client='20000000-0000-4000-8000-000000000001',now=Date.now();
  const visit={id:'30000000-0000-4000-8000-000000000001',clientId:client,workerId:null,service:'Home support',start:new Date(now-60000).toISOString(),end:new Date(now+60000).toISOString(),status:'Open',revision:1};
  const f=await fixture(b,{reads:state!=='unavailable',holdSchedule:state==='loading',scheduleStatus:state==='failed'?503:200,scheduleVisits:state==='populated'?[visit]:[],scheduleClients:state==='populated'?[{id:client,name:'Fictional client'}]:[]});
  try {
   const p=f.page;await p.setViewportSize({width,height:844});const s=p.getByRole('region',{name:'Today schedule'});await s.waitFor();
   const text=state==='populated'?/Home support.*Open/:state==='empty'?/No visits scheduled today\./:state==='unavailable'?/Schedule is unavailable/:state==='loading'?/Checking the shared schedule/:/Today’s schedule could not be verified/;
   await s.getByText(text).waitFor();assert.equal(await s.getByRole('heading',{name:'Today schedule',level:2}).count(),1);
   if(state!=='unavailable') {
    const summary=p.getByRole('heading',{name:'Today’s visits needing attention',level:2});
    assert.equal(await s.evaluate(e=>!!(e.compareDocumentPosition(e.parentElement.querySelector(':scope > h2'))&Node.DOCUMENT_POSITION_FOLLOWING)),true);
    const a=await s.boundingBox(),z=await summary.boundingBox();assert.ok(z.y>=a.y+a.height,JSON.stringify({width,state,a,z}));
   }
   assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
   assert.equal(f.requests.filter(r=>r.method==='POST').length,0);assert.deepEqual(f.unexpected,[]);assert.deepEqual(f.errors,[]);
  } finally {f.releaseSchedule();await f.context.close();}
 }} finally {await b.close();}
});
