test('in-flight retry blocks new work through changed and failed session responses',async()=>{
 const b=await chromium.launch({headless:true});try {for(const mode of ['changed','failed']){
  const f=await fixture(b,{reads:false});try{const p=f.page;await p.getByRole('button',{name:'Retry account and records'}).waitFor();f.setSessionMode(mode);f.holdNextSession();const response=p.waitForResponse(r=>new URL(r.url()).pathname==='/api/admin/session');await p.getByRole('button',{name:'Retry account and records'}).click();await p.getByRole('status').filter({hasText:'Checking account and records. Please wait.'}).waitFor();assert.equal(await p.locator('.app-shell').evaluate(e=>e.inert),true);const add=p.locator('.mobile-add-button');let blocked=false;try{await add.click({timeout:400});}catch{blocked=true;}assert.equal(blocked,true);assert.equal(await p.locator('.shared-record-editor').count(),0);f.releaseSession();const res=await response;assert.equal(res.status(),mode==='failed'?503:200);await p.waitForFunction(()=>!document.querySelector('.app-shell')?.inert);if(mode==='failed')await p.getByText('Session or record access is unverified.',{exact:false}).waitFor();else {await p.getByRole('heading',{name:'Today',exact:true}).waitFor();assert.equal(await p.getByRole('region',{name:'Today schedule'}).count(),0,'manager-only schedule is cleared on owner role');}assert.equal(await p.locator('.shared-record-editor').count(),0);assert.equal(f.requests.filter(r=>r.method==='POST').length,0);assert.deepEqual(f.unexpected,[]);assert.deepEqual(f.errors,[]);}finally{f.releaseSession();await f.context.close();}
 }}finally{await b.close();}
});
