test('enlarged phone navigation keeps whole labels and keyboard activation',async()=>{const browser=await chromium.launch({headless:true});try{for(const width of [320,390]){const f=await fixture(browser);const p=f.page;await p.setViewportSize({width,height:844});await p.waitForTimeout(100);const metrics=await p.evaluate(()=>{const nodes=[...document.querySelectorAll('body *')],sizes=nodes.map(el=>parseFloat(getComputedStyle(el).fontSize));nodes.forEach((el,i)=>el.style.setProperty('font-size',`${sizes[i]*2}px`,'important'));const nav=document.querySelector('.mobile-tabbar'),n=nav.getBoundingClientRect(),plus=document.querySelector('.mobile-add-button').getBoundingClientRect();const labels=[...nav.querySelectorAll('button span,button small')].map(el=>{const range=document.createRange();range.selectNodeContents(el);const lines=[...range.getClientRects()],r=el.getBoundingClientRect();return {text:el.textContent,lines:lines.length,rect:r.toJSON(),fits:r.left>=n.left&&r.right<=n.right&&r.top>=n.top&&r.bottom<=n.bottom};});return {nav:n.toJSON(),plus:plus.toJSON(),labels};});assert.ok(Math.abs(metrics.plus.x+metrics.plus.width/2-width/2)<1);assert.deepEqual(metrics.labels.map(x=>x.text),['Today','Schedule','Reports','Proposed','More']);assert.ok(metrics.labels.every(x=>x.lines===1&&x.fits),JSON.stringify(metrics));for(let i=0;i<metrics.labels.length;i++)for(let j=i+1;j<metrics.labels.length;j++){const a=metrics.labels[i].rect,b=metrics.labels[j].rect;assert.ok(a.right<=b.left||b.right<=a.left||a.bottom<=b.top||b.bottom<=a.top,JSON.stringify(metrics));}await p.locator('body').click({position:{x:2,y:2}});let found=false;for(let i=0;i<100;i++){await p.keyboard.press('Tab');if(await p.evaluate(()=>document.activeElement?.textContent?.trim()==='Schedule'&&document.activeElement?.closest('nav[aria-label="Primary navigation"]')!==null)){found=true;break;}}assert.ok(found,'keyboard did not reach Schedule');await p.keyboard.press('Enter');await p.getByLabel('Shared schedule').waitFor({timeout:5000});assert.deepEqual(f.unexpected,[]);assert.deepEqual(f.errors,[]);await f.context.close();}}finally{await browser.close();}});
test('enlarged phone Add and More remain keyboard accessible',async()=>{const browser=await chromium.launch({headless:true});try{for(const width of [320,390]){const f=await fixture(browser);const p=f.page;await p.setViewportSize({width,height:844});await p.evaluate(()=>{const nodes=[...document.querySelectorAll('body *')],sizes=nodes.map(el=>parseFloat(getComputedStyle(el).fontSize));nodes.forEach((el,i)=>el.style.setProperty('font-size',`${sizes[i]*2}px`,'important'));});await p.locator('body').click({position:{x:2,y:2}});let found=false;for(let i=0;i<100;i++){await p.keyboard.press('Tab');if(await p.evaluate(()=>document.activeElement?.getAttribute('aria-label')==='Add')){found=true;break;}}assert.ok(found,'keyboard did not reach Add');await p.keyboard.press('Enter');await p.getByRole('dialog',{name:'Add'}).waitFor();await p.keyboard.press('Escape');assert.equal(await p.getByRole('button',{name:'Add',exact:true}).evaluate(el=>el===document.activeElement),true);await p.getByRole('navigation',{name:'Primary navigation'}).getByRole('button',{name:'More'}).focus();await p.keyboard.press('Enter');await p.getByRole('dialog',{name:'Workspace menu'}).waitFor();assert.deepEqual(f.unexpected,[]);assert.deepEqual(f.errors,[]);await f.context.close();}}finally{await browser.close();}});
